CREATE TEMP TABLE lesson_nplusone_invoices (
  invoice_id INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL,
  issued_on DATE NOT NULL
);
INSERT INTO pg_temp.lesson_nplusone_invoices
SELECT g, 7000 + ((g - 1) % 10), DATE '2026-10-01' + ((g - 1) % 20)
FROM generate_series(1, 100) AS series(g);
CREATE TEMP TABLE lesson_nplusone_payments (
  payment_id INTEGER PRIMARY KEY,
  invoice_id INTEGER NOT NULL REFERENCES pg_temp.lesson_nplusone_invoices(invoice_id),
  status TEXT NOT NULL,
  amount NUMERIC(12,2) NOT NULL
);
INSERT INTO pg_temp.lesson_nplusone_payments
SELECT g, g, 'succeeded', (1000 + g)::NUMERIC(12,2)
FROM generate_series(1, 100) AS series(g);
CREATE TEMP TABLE lesson_request_shapes (
  strategy TEXT PRIMARY KEY,
  statement_count INTEGER NOT NULL,
  note TEXT NOT NULL
);
INSERT INTO pg_temp.lesson_request_shapes VALUES
  ('n_plus_one', 101, 'one list SELECT plus one detail SELECT per invoice'),
  ('batched_aggregate', 1, 'one grouped statement for the list');
